<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { listCanteens, listStalls, saveStall } from '../../api/admin'
import type { Canteen, Stall } from '../../api/types'
const canteens = ref<Canteen[]>([]); const rows = ref<Stall[]>([]); const canteenId = ref<number>(); const statusFilter = ref<number>(); const filteredRows = computed(() => statusFilter.value === undefined ? rows.value : rows.value.filter(r => r.status === statusFilter.value)); const dialog = ref(false)
const form = reactive({ id: undefined as number | undefined, canteenId: 1, name: '', description: '', location: '', status: 1, sort: 0 })
async function load() { rows.value = await listStalls(canteenId.value) }
function edit(row?: Stall) { Object.assign(form, row || { id: undefined, canteenId: canteenId.value || canteens.value[0]?.id || 1, name: '', description: '', location: '', status: 1, sort: 0 }); dialog.value = true }
async function save() { if (!form.name.trim()) return ElMessage.warning('请填写档口名称'); await saveStall(form); ElMessage.success('已保存'); dialog.value = false; await load() }
async function toggle(row: Stall) { await saveStall({ ...row, status: row.status ? 0 : 1 }); await load() }
onMounted(async () => { canteens.value = await listCanteens(); canteenId.value = canteens.value[0]?.id; await load() })
</script>
<template><div class="page-card"><div class="page-header"><div><h2 class="page-title">档口管理</h2><p class="page-subtitle">购物车按档口隔离，一次只能从一个档口下单。</p></div></div><div class="page-actionbar"><div class="query-area"><el-select v-model="canteenId" placeholder="选择食堂" style="width:170px" @change="load"><el-option v-for="c in canteens" :key="c.id" :label="c.name" :value="c.id" /></el-select><el-select v-model="statusFilter" placeholder="全部状态" clearable style="width:130px"><el-option label="启用" :value="1" /><el-option label="停用" :value="0" /></el-select><span class="muted">共 {{ filteredRows.length }} 个档口</span></div><div class="action-area"><el-button type="primary" @click="edit()">新增档口</el-button></div></div><el-table :data="filteredRows" stripe><el-table-column prop="id" label="ID" width="80" /><el-table-column prop="name" label="档口" /><el-table-column prop="location" label="位置" /><el-table-column prop="description" label="说明" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="160"><template #default="{ row }"><el-button text type="primary" @click="edit(row)">编辑</el-button><el-button text @click="toggle(row)">{{ row.status ? '停用' : '启用' }}</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="form.id ? '编辑档口' : '新增档口'" width="480px"><el-form label-position="top"><el-form-item label="所属食堂"><el-select v-model="form.canteenId" style="width:100%"><el-option v-for="c in canteens" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item><el-form-item label="档口名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="位置"><el-input v-model="form.location" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
